    getFormatDay: function getFormatDay(value) {
      if (value) {
        var arrs = value.split('-');
        if (arrs && arrs.length == 3) {
          return "".concat(arrs[1], " - ").concat(arrs[2]);
        } else {
          return value;
        }
      }
      return '';
    },
    getnum: function getnum(hasnum, allnum) {
      var num = (hasnum / allnum * 100).toString();
      var aNew;
      var re = /([0-9]+\.[0-9]{2})[0-9]*/;
      aNew = num.replace(re, "$1");
      return Number(aNew);
    },
    getProgressValue: function getProgressValue(num) {
      if (isNaN(num)) {
        return 0;
      }
      var ns = JSON.stringify(num);
      var nsArr = ns.split('.');
      if (nsArr && nsArr.length == 2) {
        var length = 0;
        for (var i = 0; i < nsArr[1].length; i++) {
          var c = nsArr[1][i];
          if (c > 0) {
            length = i + 2;
            break;
          }
        }
        ns = num.toFixed(length);
        ns = Number(Number(ns * 100).toFixed(length));
      }
      return ns;
    },
    getRegionCode: function getRegionCode(length) {
      if (this.userDetail && this.userDetail.regionCode && this.userDetail.regionCode.length == length) {
        return true;
